import{_ as o}from"./chunks/hinweise-it-dienstleister.aprHqZOH.js";import{_ as h,o as u,c,j as e,a as n,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const t="/bilder/installation/installation-svws-server-ziel-ordner.png",a="/bilder/installation/installation-svws-server-konfiguration.png",s="/bilder/installation/installation-svws-server-zertifikat.png",d="/bilder/installation/installation-svws-server-migration.png",l="/bilder/installation/installation-svws-server-installationsprozess.png",g="/bilder/installation/installation-svws-server-zertifikat-installieren-testkonfiguration.png",m="/bilder/installation/installationsverzeichnis.png",S="/bilder/installation/arbeitsverzeichnis.png",p="/bilder/installation/con-standalone.png",f="/bilder/installation/installationsverzeichnis-server.png",b="/bilder/installation/arbeitsverzeichnis-server.png",k="/bilder/installation/con-server-client.png",D="/bilder/installation/installation-svws-server-zertifikat-installieren.png",w="/bilder/installation/svws-server-installation-update.png",N=JSON.parse('{"title":"SVWS-Server und SchILD-NRW 3 installieren","description":"","frontmatter":{"title":"SVWS-Server und SchILD-NRW 3 installieren","source_pageid":852,"source_revision":7228},"headers":[],"relativePath":"administration/installation/installation-svws-server-und-schild-nrw-3.md","filePath":"administration/installation/installation-svws-server-und-schild-nrw-3.md"}'),v={name:"administration/installation/installation-svws-server-und-schild-nrw-3.md"};function z(W,r,I,V,A,P){return u(),c("div",null,[...r[0]||(r[0]=[e("h1",{id:"svws-server-und-schild-nrw-3-installieren",tabindex:"-1"},[n("SVWS-Server und SchILD-NRW 3 installieren "),e("a",{class:"header-anchor",href:"#svws-server-und-schild-nrw-3-installieren","aria-label":'Permalink to "SVWS-Server und SchILD-NRW 3 installieren"'},"​")],-1),e("p",null,"Installieren Sie die Programmbausteine für einen Einzelplatz oder einen Windows-Server mit Clients. Die Anleitung behandelt auch Zertifikate, Verbindungsdateien, Updates und Deinstallation.",-1),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,"Die Versionen des SVWS-Servers und von SchILD-NRW 3 müssen zusammenpassen. Kontrollieren Sie vor Beginn der Installation, dass Sie die korrekten Installer vorliegen haben.")],-1),i('<p>Der folgende Artikel beinhaltet Hinweise zur Installation des SVWS-Servers und von SchILD-NRW 3.</p><h2 id="ubersicht-uber-die-programmbausteine" tabindex="-1">Übersicht über die Programmbausteine <a class="header-anchor" href="#ubersicht-uber-die-programmbausteine" aria-label="Permalink to &quot;Übersicht über die Programmbausteine&quot;">​</a></h2><p><img src="'+o+'" alt="Auswahl des Ziel-Ordners" loading="lazy"></p><p><em>Auswahl des Ziel-Ordners</em></p><p>Für den Betrieb werden vier Bausteine benötigt: die Datenbank <strong>MariaDB</strong>, der <strong>SVWS-Server</strong>, der browserbasierte <strong>SVWS-Client</strong> und das Windows-Programm <strong>SchILD-NRW 3</strong>. Der SVWS-Server läuft als Dienst und übernimmt die Verarbeitung und Bereitstellung von Daten.</p><p>SchILD-NRW 3 dient als Anzeigeoberfläche der Datenbankdaten und übernimmt ebenfalls logische Aufgaben, die noch nicht im SVWS-Server implementiert wurden. SchILD-NRW 3 greift deshalb teilweise über den SVWS-Server und teilweise direkt auf die MariaDB zu.</p><p>Der SVWS-Client stellt die Technologie zur Anzeige der Datenbankdaten in einem Browserfenster zur Verfügung. Der SVWS-Client ist Bestandteil des SVWS-Servers und kann nur auf die logischen Aufgaben des SVWS-Servers zurückgreifen. Der SVWS-Server und SchILD-NRW 3 arbeiten ausschließlich mit einer MariaDB zusammen. Für den Zugriff auf die MariaDB ist kein ODBC-Treiber notwendig.</p><p>Es werden <strong>zwei Installationsdateien</strong> ausgeliefert:</p><ul><li>Das eine Installationsprogramm installiert den <strong>SVWS-Server mit der MariaDB</strong>, dem SVWS-Client und benötigten Komponenten. Während der Installation des SVWS-Clients können bestehende SchILD-NRW 2 Datenbanken (Access MDB, MariaDB, MySQL, Microsoft SQL-Server) in die neue MariaDB migriert werden. Zudem wird eine Zertifikatsdatei erzeugt, welche im Zertifikatsspeicher des Betriebssystems hinterlegt werden muss.</li><li>Das andere Installationsprogramm installiert <strong>SchILD-NRW 3</strong> und stellt eine Verknüpfung zwischen SchILD-NRW 3 und der MariaDB her.</li></ul><h2 id="wichtige-begriffe-und-konzepte" tabindex="-1">Wichtige Begriffe und Konzepte <a class="header-anchor" href="#wichtige-begriffe-und-konzepte" aria-label="Permalink to &quot;Wichtige Begriffe und Konzepte&quot;">​</a></h2><h3 id="datenbank-schema" tabindex="-1">Datenbank-Schema <a class="header-anchor" href="#datenbank-schema" aria-label="Permalink to &quot;Datenbank-Schema&quot;">​</a></h3><p>Ein <strong>Datenbankschema</strong> bezeichnet hier die Datenbank einer Schule innerhalb der MariaDB. Es enthält die von SVWS benötigten Tabellen und kann leer, bereits befüllt oder aus SchILD-NRW 2 migriert sein. „Schema“ bedeutet daher nicht, dass noch keine Schuldaten vorhanden sind.</p><p>In einem MariaDB-Datenbankmanagementsystem können mehrere Datenbanken (Schemas) verwaltet werden, die dann jeweils die Daten einer Schule enthalten, auf die mit dem SchILD-Client gesondert zugegriffen werden kann.</p><p>In großen Systemen, etwa kommunalen Rechenzentren oder kommerziellen Rechenzentren, könnten noch weitere Schemata in der MariaDB laufen, die dann anderen Schulen gehören oder gar nichts mit Schulen zu tun haben.</p><h3 id="die-unterschiedlichen-nutzer" tabindex="-1">Die unterschiedlichen Nutzer <a class="header-anchor" href="#die-unterschiedlichen-nutzer" aria-label="Permalink to &quot;Die unterschiedlichen Nutzer&quot;">​</a></h3><ul><li>Der <strong>Root-Benutzer</strong> verwaltet den gesamten MariaDB-Server. Er kann Datenbanken und weitere Datenbank-Benutzer anlegen oder löschen. Diese technischen Zugangsdaten gehören zur zuständigen IT. Ein vergessenes root-Kennwort muss administrativ wiederhergestellt werden; Ihr persönliches SchILD-Kennwort ersetzt diesen Zugang nicht.</li><li>Der <strong>Datenbank-Benutzer</strong> verbindet SchILD-NRW 3 mit der Schuldatenbank. Diese einzelne Datenbank heißt auch <strong>Schema</strong>; deshalb wird der Zugang auch Schema-Benutzer genannt. Im beschriebenen Aufbau erhält er Administrationsrechte auf dieses Schema. Welche Datenbanken er tatsächlich verwenden oder löschen darf, legen die MariaDB-Berechtigungen fest. Derselbe Benutzername kann für mehrere Schemata berechtigt sein. In den Beispielen heißt dieser technische Zugang <strong>svwsadmin</strong>.</li><li>Mit einem <strong>SchILD-NRW-3-Benutzer</strong> meldet sich eine Person zur täglichen Arbeit an. Die Benutzerverwaltung legt fest, welche Funktionen diese Person verwenden darf. Mit SchILD-Administrationsrechten stehen zusätzliche Funktionen der Programmoberfläche zur Verfügung. Diese Berechtigungen sind von den Rechten des technischen Datenbank-Zugangs zu unterscheiden.</li></ul><h3 id="die-ordnerstruktur" tabindex="-1">Die Ordnerstruktur <a class="header-anchor" href="#die-ordnerstruktur" aria-label="Permalink to &quot;Die Ordnerstruktur&quot;">​</a></h3><p>Um die Sicherheit des Betriebssystems zu gewährleisten, stattet Windows die unterschiedlichen Ordner mit unterschiedlichen Rechten aus. Der SVWS-Server und SchILD-NRW 3 fügen sich hier in diesem Sinne korrekt ein. Für die Benutzung des SVWS-Servers und SchILD-NRW werden vier unterschiedliche Verzeichnisse verwendet.</p><ul><li>Das Verzeichnis, in dem der SVWS-Server <em>installiert</em> wird. In diesem Verzeichnis sollen Nutzer nichts ablegen können und keinen Zugriff darauf haben.</li><li>Das Verzeichnis, in dem der SVWS-Server die Datenbanken ablegt. In diesem Verzeichnis hat nur der Server Zugriff, Nutzer sollen hier nichts lesen oder verändern können.</li><li>Das Verzeichnis, in dem das reine Programm SchILD-NRW3 installiert wird. Nutzer haben hier keine Schreibrechte und es werden hier keine Arbeitsdaten erstellt.</li><li>Das SVWS-Arbeitverzeichnis, in dem die Daten der Nutzer liegen, zum Beispiel die Reports oder die Export- und Importdateien. Hier haben Nutzer für die tägliche Arbeit Zugriff.</li></ul><h2 id="vorbereitende-maßnahmen" tabindex="-1">Vorbereitende Maßnahmen <a class="header-anchor" href="#vorbereitende-maßnahmen" aria-label="Permalink to &quot;Vorbereitende Maßnahmen&quot;">​</a></h2><p>Sofern Sie einen Wechsel von SchILD-NRW 2 nach SchILD-NRW 3 mit SVWS-Server durchführen wollen, empfehlen wir Ihnen einige vorbereitende Maßnahmen in SchILD-NRW 2:</p><ol><li><strong>Datenbank sichern:</strong> Sichern Sie zunächst die vorhandene Datenbank, bevor Sie die weiteren Schritte durchführen. Achten Sie darauf, dass keine weitere Person auf die Datenbank zugreift.</li><li><strong>Papierkorb leeren:</strong> Rufen Sie den Menüpunkt <em>Auswahl ➜ Papierkorb zeigen</em> auf. Löschen Sie alle Schüler im Papierkorb, um unvollständige Datensätze bei der Migration zu vermeiden.</li><li><strong>Datensätze reduzieren:</strong> Rufen Sie den Menüpunkt <em>Extras ➜ Löschfristen prüfen</em> auf. Löschen Sie alle Daten gemäß VO-DV I und VO-DV II um die Vorgaben einzuhalten und die Datenmenge zu reduzieren.</li><li><strong>Datenbank automatisch prüfen:</strong> Rufen Sie den Menüpunkt <em>Extras ➜ Automatische Prozesse ausführen</em> auf. Die Datenbank wird in der Folge auf grundlegende Konsistenzen überprüft. Fehlende Konsistenzen werden angelegt.</li><li><strong>Datenbank komprimieren und reparieren:</strong> Rufen Sie den Menüpunkt <em>Datei ➜ Datenbank komprimieren und reparieren</em> auf. Dieser Prozess entfernt unnötigen Ballast, der sich bei der Arbeit mit der Datenbank angesammelt hat.</li><li><strong>Optional - Migrationstool verwenden:</strong> Die Migration in eine neue SchILD-NRW 2 Datenbank kann hertnäckige Probleme beheben.</li></ol><h2 id="einzelplatzinstallation" tabindex="-1">Einzelplatzinstallation <a class="header-anchor" href="#einzelplatzinstallation" aria-label="Permalink to &quot;Einzelplatzinstallation&quot;">​</a></h2><p>Im Folgenden wird die Installation von SchILD-NRW 3 und dem SVWS-Server auf einem Einzelplatzrechner vorgestellt. In produktiven Schulumgebungen wird diese Form der Installation eher selten vorkommen.</p><p>Insbesondere in der Entwicklungsphase bietet diese Installation eine einfache und schnelle Möglichkeit, das Programm zu testen. Die veröffentlichten Versionen finden Sie im <a href="https://github.com/SVWS-NRW/Schild-NRW-3/releases" target="_blank" rel="noreferrer">Release-Bereich von SchILD-NRW 3</a> und im unten verlinkten Release-Bereich des SVWS-Servers. Für die Installation der Komponenten sind Administrationsrechte am Arbeitsplatz-PC notwendig.</p><h3 id="installationsanleitungen-als-video-tutorials" tabindex="-1">Installationsanleitungen als Video-Tutorials <a class="header-anchor" href="#installationsanleitungen-als-video-tutorials" aria-label="Permalink to &quot;Installationsanleitungen als Video-Tutorials&quot;">​</a></h3><p>Das Video zeigt einen älteren Installationsstand. Die dort genannten Standardordner und der Name der Zugangsdatei stimmen nicht vollständig mit der schriftlichen Anleitung überein. Verwenden Sie für diese Angaben die schriftlichen Installationsschritte auf dieser Seite.</p><h3 id="installationsumfang" tabindex="-1">Installationsumfang <a class="header-anchor" href="#installationsumfang" aria-label="Permalink to &quot;Installationsumfang&quot;">​</a></h3><p>Die neuste Version kann hier heruntergeladen werden: <a href="https://github.com/SVWS-NRW/SVWS-Server/releases" target="_blank" rel="noreferrer">https://github.com/SVWS-NRW/SVWS-Server/releases</a></p><p>Installiert werden</p><ol><li>Ein Maria-Datenbankmanagementsystem <ul><li>Das Datenbankmanagementsystem steuert den Multiuserzugriff auf die Datenbanken</li><li>Das Programm wird im Ordner <code>C:\\Programme\\SVWS-Server\\db</code> gespeichert</li><li>Die Datenbankdateien werden im Verzeichnis <code>C:\\ProgramData\\SVWS-Server\\data</code> gespeichert</li><li>Die Kennwörter für den Zugriff auf die Datenbanken werden in der Datei <code>C:\\ProgramData\\SVWS-Server\\res\\svwsconfig.json</code> gespeichert</li></ul></li><li>Eine Java-Laufzeitumgebung <ul><li>Dieses Programm ist notwendig, um den SVWS-Server auszuführen.</li><li>Die Laufzeitumgebung wird im Ordner <code>C:\\Programme\\SVWS-Server\\java</code> gespeichert</li></ul></li><li>Der SVWS-Server <ul><li>Der SVWS-Server fungiert als Dienstprogramm, welches logische Aufgaben übernimmt und den Zugriff auf die MariaDB-Datenbank regelt.</li><li>Das Programm wird im Ordner <code>C:\\Programme\\SVWS-Server\\svws-server</code> gespeichert.</li><li>Log-Dateien werden im Ordner <code>C:\\ProgramData\\SVWS-Server\\logs</code> gespeichert. Die Log-Dateien enthalten Informationen zu Fehlern bei der Ein- und Ausgabe des SVWS-Servers.</li></ul></li><li>Der SVWS-Client <ul><li>Der SVWS-Cient ermöglicht den browserbasierten Zugriff auf die Datenbanken und greift auf logische Aufgaben des SVWS-Servers zurück. Der SVWS-Client übernimmt die Aufgaben der Programme LuPO und Kurs42.</li><li>Der Client wird im Ordner <code>C:\\ProgramData\\SVWS-Server\\client</code> installiert.</li></ul></li><li>Eine SSL-Zertifikatsdatei <ul><li>Das Zertifikat muss später im System angemeldet werden, damit der SVWS-Client im Browser ohne Sicherheitswarnung gestartet werden kann.</li><li>Die SSL-Zertifikatsdatei wird im Ordner <code>C:\\Users\\&lt;benutzername&gt;\\Dokumente\\SVWS.cer</code> gespeichert.</li></ul></li></ol><h3 id="installation-des-svws-servers" tabindex="-1">Installation des SVWS-Servers <a class="header-anchor" href="#installation-des-svws-servers" aria-label="Permalink to &quot;Installation des SVWS-Servers&quot;">​</a></h3><p><img src="'+t+'" alt="Auswahl des Zielordners" loading="lazy"></p><p><em>Auswahl des Zielordners</em></p><p>Führen Sie die Datei win64-installer-version.exe aus.</p><p>Es folgt ein Hinweisfenster der Benutzerkontensteuerung, dass durch die Installation Änderungen am Gerät vorgenommen werden. Klicken Sie hier auf die Schaltfläche <code>Weiter</code>.</p><p>Im folgenden Fenster akzeptieren Sie die Lizenzvereinbarung für die Installation des SVWS-Servers.</p><p>Anschließend können Sie die Installationspfade für das Datenbanksystem und das Programmverzeichnis auswählen. Für die lokale Einzelplatzinstallation empfehlen wir dringend, die vorgeschlagenen Pfade nicht zu ändern.</p><p><img src="'+a+'" alt="Konfigurieren der Installation" loading="lazy"></p><p><em>Konfigurieren der Installation</em></p><p>Es folgen die Konfigurationsangaben der SVWS-Server-Installation. Aktivieren Sie hier das Auswahlfeld zu &quot;Migriere aus einem Schild v2.x - Schema&quot;, damit während des Installationsprozesses die Daten einer SchILD-NRW 2 - Datenbank in die MariaDB migriert werden. Alle anderen Auswahlfelder sollten Sie so belassen.</p><p>Wenn die MariaDB installiert wird, wird automatisch ein Benutzer mit dem Namen &quot;root&quot; erzeugt. Dieser Benutzer hat als Super-Admin volle Zugriffsrechte auf alle Datenbanken, kann diese erzeugen und löschen. Legen Sie das root-Kennwort für diesen Benutzer fest und notieren Sie sich das Kennwort.</p><p>Der Installer schlägt Ihnen bereits ein sehr sicheres Kennwort vor, welches von einem Zufallsgenerator erzeugt wurde. Verwahren Sie dieses Kennwort an einem sichern Ort.</p>',43),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,[e("strong",null,"Bewahren Sie das root-Kennwort bei der zuständigen IT auf. Geht es verloren, muss diese den administrativen Zugang wiederherstellen; ein persönliches SchILD-Kennwort genügt dafür nicht.")]),e("p",null,"Jede Person mit Kenntnis des root-Kennworts kann sich als Super-Admin an allen Datenbanken anmelden.")],-1),i('<p>Sie können zudem den Port für den Zugriff auf die MariaDB eingeben. Der Port ergänzt den Datenbank-Host für den direkten MariaDB-Zugriff, etwa Host <code>localhost</code> mit Port <code>3306</code>. Hier wird <strong>kein <code>https://</code></strong> vorangestellt. Die HTTPS-Adresse gehört zur getrennten Verbindung mit dem SVWS-Server.</p><p>Als Standard ist hier der Port 3306 eingetragen. Sie müssen die Portnummer nur dann ändern, wenn der Port 3306 bereits durch eine andere Anwendung belegt wird. Dies kann z.B. dann der Fall sein, wenn Sie ein anderes datenbankbasiertes Programm oder einen anderen datenbankbasierten Dienst installiert haben. Erhöhen Sie in einem solchen Fall die Portnummer z.B. auf 3307.</p><p>Vergeben Sie einen Namen für das Datenbank-Schema. Bei dem Datenbank-Schema handelt es sich um eine leere Datenbank, in der bereits alle Notwendigen Tabellen angelegt wurden. Im Gegensatz zu SchILD-NRW 2 gibt es keine Standarddatenbank. Jede Datenbank in SchILD-NRW 3 muss einen hier zu definierenden Namen erhalten.</p><p>Legen Sie einen <strong>Datenbank-Benutzer</strong> mit Kennwort an. Der Installer schlägt ein zufällig erzeugtes Kennwort vor. Dieser technische Zugang erhält Administrationsrechte auf die hier eingerichtete Schuldatenbank und wird von SchILD-NRW 3 für die Verbindung verwendet. Er gehört keiner bestimmten Person. Anders als der root-Zugang ist er im beschriebenen Aufbau auf diese eine Datenbank beschränkt.</p><p>Notieren Sie Benutzername und Kennwort für die Einrichtung der Verbindung und bewahren Sie die Angaben bei der zuständigen IT auf. Der root-Benutzer kann das Kennwort bei Bedarf zurücksetzen oder einen anderen Zugang für die Schuldatenbank einrichten.</p><p>Klicken Sie auf die Schaltfläche <code>Weiter</code>.</p><p><img src="'+s+'" alt="Angaben zum SSL-Zertifikat" loading="lazy"></p><p><em>Angaben zum SSL-Zertifikat</em></p><p>Im folgenden Fenster geben Sie den Zertifikatsnamen, den Schulnamen und den Schulort für die Zertifikatsdatei ein. Die Zertifikatsdatei wird während des Installationsprozesses erzeugt und muss in einem späteren Schritt im Betriebssystem installiert werden.</p><p><img src="'+d+'" alt="Zu migrierende Datenbank wählen" loading="lazy"></p><p><em>Zu migrierende Datenbank wählen</em></p><p>Wenn Sie das Auswahlfeld &quot;Migriere aus einem Schild v2.x - Schema&quot; aktiviert hatten, folgt nun ein Fenster, in welchem Sie Angaben zur Migration einer SchILD-NRW 2 - Datenbank vornehmen müssen. Wählen Sie hier das Datenbankformat der SchILD-NRW 2-Datenbank aus (Access MDB, MariaDB, MySQL, Microsoft SQL-Server).</p><p>Bei der Migration einer Access MDB müssen Sie den Dateipfad zur Access MDB angeben (z.B. schild200n.mdb). Bei der Migration einer MariaDB, MySQL- oder Microsoft SQL-Server-Datenbank müssen Sie einen Benutzernamen mit vollen Zugriffsrechten auf die Datenbank angeben. Zudem das zugehörige Passwort, den Ort der Datenbank (z.B. localhost oder IP 192.168.1.x) und den Namen des Schemas der Datenbank.</p><p><img src="'+l+'" alt="Info-Fenster während des Installationsprozesses" loading="lazy"></p><p><em>Info-Fenster während des Installationsprozesses</em></p><p>Im Anschluss können Sie die Installation starten. Während des Installationsprozesses wird die MariaDB installiert, der SVWS-Server installiert, die benötigte Java-Bibliothek installiert, die Konfigurationsdatei mit den Zugangsdaten auf die MariaDB gespeichert, die Zertifikatsdatei gespeichert und der SVWS-Server als Dienst gestartet. Im Anschluss wird noch die SchILD-NRW 2-Datenbank in das SchILD-NRW 3-Schema migriert.</p><p>Ein Anzeigefenster informiert Sie über den Fortschritt der Installation. Insbesondere die Migration der Datenbank kann einige Zeit in Anspruch nehmen.</p><h3 id="installation-des-ssl-zertifikats" tabindex="-1">Installation des SSL-Zertifikats <a class="header-anchor" href="#installation-des-ssl-zertifikats" aria-label="Permalink to &quot;Installation des SSL-Zertifikats&quot;">​</a></h3><p><img src="'+g+'" alt="Zertifikat installieren" loading="lazy"></p><p><em>Zertifikat installieren</em></p><p>Damit der SVWS-Client ohne störenden Sicherheitshinweis im Browser gestartet werden kann, muss das SSL-Zertifikat, welches während des Installationsprozesses des SVWS-Servers erzeugt und gespeichert wurde, im Zertifikatsspeicher des Betriebssystems abgespeichert werden.</p><p>Windows hält hierzu einen einfachen Zertifikatimport-Assistenten bereit, welcher das SSL-Zertifikat in den Zertifikatsspeicher kopiert und am System anmeldet.</p><p>Navigieren Sie zum Windows-Systemordner &quot;Dokumente&quot;. Dort finden Sie eine Zertifikatsdatei mit dem Namen SVWS.cer. Führen Sie mit Hilfe eines Doppelklicks den Zertifikatimport-Assistenten aus.</p><p>Alternativ können Sie mit einem Rechtsklick den Kontextmenüeintrag &quot;Zertifikat installieren&quot; wählen. Es öffnet sich ein Informationsfenster mit Hinweisen zum Zertifikat. Klicken Sie auf die Schaltfläche <code>Zertifikat installieren</code>.</p><ol><li>Wählen Sie als Speicherort <strong>Lokaler Computer</strong>. Dafür benötigen Sie Windows-Administrationsrechte.</li><li>Klicken Sie auf <strong>Weiter</strong> und wählen Sie <strong>Alle Zertifikate in folgendem Speicher speichern</strong>.</li><li>Klicken Sie auf <strong>Durchsuchen…</strong> und wählen Sie <strong>Vertrauenswürdige Stammzertifizierungsstellen</strong>.</li><li>Bestätigen Sie mit <strong>OK</strong> und anschließend mit <strong>Weiter</strong>.</li></ol><p>Schließen Sie den Prozess mit Klick auf die Schaltfläche <code>Fertig stellen</code> ab. Ein Hinweisfenster informiert Sie über den erfolgreichen Import des Zertifikats.</p><h3 id="start-des-svws-client-im-browser" tabindex="-1">Start des SVWS-Client im Browser <a class="header-anchor" href="#start-des-svws-client-im-browser" aria-label="Permalink to &quot;Start des SVWS-Client im Browser&quot;">​</a></h3><p>Starten Sie einen Browser (Chrome, Edge, Firefox etc.). Rufen Sie in der Adresszeile den SVWS-Client auf, indem Sie die Adresse <strong><a href="https://servername" target="_blank" rel="noreferrer">https://servername</a></strong> eingeben. Es empfiehlt sich, einen Favoriten für diesen Link anzulegen. Sie können alternativ einen Browserlink zu dieser Adresse auf dem Desktop des PCs ablegen.</p><h3 id="installation-von-schild-nrw-3" tabindex="-1">Installation von SchILD-NRW 3 <a class="header-anchor" href="#installation-von-schild-nrw-3" aria-label="Permalink to &quot;Installation von SchILD-NRW 3&quot;">​</a></h3><p><img src="'+m+'" alt="Auswahl des Zielordners" loading="lazy"></p><p><em>Auswahl des Zielordners</em></p><p>Laden Sie das Installationspaket für den vorgesehenen Programmstand aus den <a href="https://github.com/SVWS-NRW/Schild-NRW-3/releases" target="_blank" rel="noreferrer">offiziellen SchILD-NRW-3-Releases</a> herunter. Achten Sie auf die dort genannte passende SVWS-Server-Version.</p><p>Installiert werden</p><ol><li>SchILD-NRW 3 im Ordner <code>C:\\Programme (x86)\\SchILD3.0</code>, auf das nur lesende Rechte notwendig sind</li><li>ein Arbeitsverzeichnis im Ordner <code>C:\\SVWS-Arbeitsverzeichnis</code>, auf welches lesende und schreibende Rechte notwendig sind. Dieser Ordner wird z.B. die Connection-Dateien zur MariaDB und die Reports aufnehmen.</li><li>eine Connection-Datei schemaname.con im Ordner <code>C:\\SVWS-Arbeitsverzeichnis\\Connection-Files</code>. Die Connection-Datei (früher udl-Datei) ist eine Textdatei, welche Verbindungsdaten zur MariaDB enthält und in einem Texteditor geöffnet werden kann.</li></ol><p>Führen Sie die Datei Setup_SchILD3_vXYZ.exe aus. Es folgt ein Hinweisfenster der Benutzerkontensteuerung, dass durch die Installation Änderungen am Gerät vorgenommen werden. Klicken Sie hier auf die Schaltfläche <code>Weiter</code>.</p><p>Wählen Sie im folgenden Fenster den Installationsordner des Programms. Wir empfehlen, für die Einzelplatzinstallation den Ordner nicht zu ändern. Klicken Sie hier auf die Schaltfläche <code>Weiter</code>.</p><p><img src="'+S+'" alt="Auswahl des Zielordners" loading="lazy"></p><p><em>Auswahl des Zielordners</em></p><p>Wählen Sie nun, wo das SVWS-Arbeitsverzeichnis erstellt werden soll. Für die Einzelplatzinstallation empfehlen wir den vorgegebenen Ordner im Hauptverzeichnis <code>C:\\SVWS-Arbeitsverzeichnis</code> oder alternativ im Benutzerverzeichnis <code>Dokumente\\SVWS-Arbeitsverzeichnis</code>. Klicken Sie hier auf die Schaltfläche <code>Weiter</code>.</p><p>Sie können nun angeben, unter welchem Programmnamen SchILD-NRW 3 im Startmenü und auf dem Desktop angezeigt werden soll. Wir empfehlen dringend, den vorgegebenen Namen nicht zu ändern. Klicken Sie hier auf die Schaltfläche <code>Weiter</code>.</p><p>SchILD-NRW 3 wird nun installiert. Ein Hinweisfenster informiert Sie über die erfolgreiche Installation und den Aufruf eines externen Programms zur Einrichtung der Konfigurationsdatei.</p>',41),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Pfad des SVWS-Arbeitsverzeichnisses"),e("p",null,[n("Beachten Sie an dieser Stelle unbedingt die Pfade des SVWS-Arbeitsverzeichnisses und des SchILD-Installationsverzeichnisses. Zum Beispiel könnten diese auf dem "),e("strong",null,"Server"),n(" auf Laufwerk D: installiert werden und würden dann zum Beispiel (!) auf "),e("code",null,"D:\\Schulprogramme\\SchILD-NRW3\\"),n(" und "),e("code",null,"D:\\Schulprogramme\\SVWS-Arbeitsverzeichnis\\"),n(" installiert werden.")]),e("p",null,[e("strong",null,"Im eigentlichen Netzwerk jedoch wären diese Ordner als Freigaben auf den Client-Rechnern"),n(" wieder einzubinden und hier können dann andere Namen verwendet werden, zum Beispiel als "),e("code",null,"S:\\SchILD-NRW3"),n(" und "),e("code",null,"S:\\SVWS-Arbeitsverzeichnis"),n(" oder auch als Pfade ohne Laufwerksbuchstaben.")]),e("p",null,[n("Achten Sie darauf, dass die Datei "),e("em",null,"Admin.ini"),n(" im SchILD-NRW-3-Installationsverzeichnis NICHT auf den Serverpfad verweist, sondern auf den Pfad, den die Rechner im Netzwerk sehen!")])],-1),e("h4",{id:"die-verbindung-mit-schild-dbconfig-exe-konfigurieren",tabindex:"-1"},[n("Die Verbindung mit SchILD_DBConfig.exe konfigurieren "),e("a",{class:"header-anchor",href:"#die-verbindung-mit-schild-dbconfig-exe-konfigurieren","aria-label":'Permalink to "Die Verbindung mit SchILD_DBConfig.exe konfigurieren"'},"​")],-1),e("p",null,[e("img",{src:p,alt:"Konfiguration der Connection-Datei",loading:"lazy"})],-1),e("p",null,[e("em",null,"Konfiguration der Connection-Datei")],-1),e("p",null,"Direkt nach der Installation öffnet sich das Konfigurationstool, mittels dem die Datei erstellt wird, die notwendig ist, damit SchILD3 auf das Datenbankschema zugreifen kann.",-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Das Konfigurationstool kann bei Bedarf auch nachträglich aufgerufen werden, hierzu einfach die "),e("em",null,"SchILD_DBConfig.exe"),n(" im Installationsverzeichnis von SchILD3 als Windows-Administrator ausführen.")])],-1),i('<p>Im folgenden Fenster können Sie nun alle voreingetragenen Angaben prüfen, welche zur Erstellung einer Konfigurationsdatei notwendig sind.</p><ul><li>Als <strong>Server</strong> einer Einzelplatzinstallation ist entweder <code>localhost</code> oder der <code>Computername</code> eingetragen. Beide Eintragungen sind gleichberechtigt korrekt</li><li>Als <strong>Port</strong> ist der während der Installation des SVWS-Servers angegebene Port zur Datenbank eingetragen. Der Standard ist <code>3306</code>.</li><li>Als <strong>Datenbankschema</strong> ist der während der Installation des SVWS-Servers angegebene Name des Datenbankschemas eingetragen. Der Standardname lautet <code>svwsdb</code>.</li><li>Als <strong>Benutzername</strong> ist der während der Installation des SVWS-Servers angegebene Benutzername eingetragen. Der Standardbenutzer ist <code>svwsadmin</code>.</li><li>Als <strong>Benutzerpasswort</strong> ist das während der Installation des SVWS-Servers angegebene Benutzerpasswort für den Zugriff auf die Datenbank eingetragen.</li><li>Als <strong>URL für SVWS-Server</strong> ist die URL eingetragen, die im Browser zum Start des SVWS-Client eingetragen werden muss. Der Standard ist <code>https://Servername</code> oder <code>https://Server-IP-Adresse</code>. Beide Angaben sind gleichberechtigt korrekt.</li><li>Als <strong>Port</strong> für den Zugriff des SVWS-Clients auf die Datenbank ist der Port <code>443</code> eingetragen. Dies ist der Standard-Port für den verschlüsselten Zugriff des SVWS-Clients auf die Datenbank.</li><li>Durch das Auswahlfeld <code>Beim Verbindungstest berücksichtigen</code> kann dieser verschlüsselte SSL-Zugriff ebenfalls getestet werden, bevor die Konfigurationsdatei erzeugt wird. Die Aktivierung des Häkchens wird empfohlen.</li><li>Optional: Angaben zum Proxy-Server</li><li>Als <strong>Verzeichnis für die Konfigurationsdatei</strong> (Connection-File) wird standardmäßig ein Unterverzeichnis im SVWS-Arbeitsverzeichnis angeboten. Wir empfehlen die Einstellung unverändert zu übernehmen. Der Standardpfad lautet <code>C:\\SVWS-Arbeitsverzeichnis\\Connection-Files</code></li><li>Im letzten Feld können Sie einen <strong>Namen für die Konfigurationsdatei</strong> vergeben. Wir empfehlen hier den gleichen Namen zu verwenden, den auch das Schema trägt. So fällt eine Zuordnung der Konfigurationsdatei zum Schema leichter. Der Standardname ist <code>svwsdb</code></li></ul><p>Führen Sie die Verbindungstests für MariaDB und SVWS aus. Beide Tests müssen mit den eingetragenen Ports erfolgreich sein. Klicken Sie anschließend auf <strong>Datei speichern</strong>. Bestätigen Sie die Meldung über die gespeicherte Konfigurationsdatei und schließen Sie das Fenster mit <strong>Schließen</strong>.</p><h3 id="start-der-programme" tabindex="-1">Start der Programme <a class="header-anchor" href="#start-der-programme" aria-label="Permalink to &quot;Start der Programme&quot;">​</a></h3><p>SchILD-NRW 3 kann wie gewohnt über einen Doppelklick auf das Desktopsymbol oder über einen Einfachklick auf das Symbol im Startmenü gestartet werden.</p><p>Zum Start des SVWS-Clients öffnen Sie einen Browser. Tippen Sie dann in die Adresszeile die URL zum SVWS-Client ein (<code>https://localhost</code> oder <code>https://Computername</code>).</p><p>Für den Zugriff auf beide Programme müssen Sie sich als SchILD-Benutzer anmelden. Verwenden Sie hier die gleichen Zugangsdaten, die sie auch in SchILD-NRW 2 verwendet haben.</p><p>SchILD-NRW 3 und der SVWS-Client greifen gleichermaßen auf die MariaDB zu. Beide Programme verfügen über ebenbürtige Eintragungsmöglichkeiten, aber auch über unterschiedliche. So enthält der SVWS-Client die Funktionen von LuPO und Kurs42, während SchILD-NRW 3 Abiturberechnungen enthält.</p><p>In den kommenden Monaten werden die Fähigkeiten des SVWS-Clients stetig ausgebaut, so dass dieser später die gleichen Funktionalitäten enthalten wird, wie SchILD-NRW 3.</p><h2 id="windows-server-client-installation" tabindex="-1">Windows Server-Client-Installation <a class="header-anchor" href="#windows-server-client-installation" aria-label="Permalink to &quot;Windows Server-Client-Installation&quot;">​</a></h2><p>Im Folgenden wird die Installation von SchILD-NRW 3 und dem SVWS-Server in einer Server-Client-Umgebung vorgestellt. In produktiven Schulumgebungen wird diese Form der Installation der Standardfall sein.</p><p>Für die Installation der Komponenten sind Administrationsrechte an allen PCs notwendig.</p><h3 id="installationsumfang-1" tabindex="-1">Installationsumfang <a class="header-anchor" href="#installationsumfang-1" aria-label="Permalink to &quot;Installationsumfang&quot;">​</a></h3><p>Installiert werden</p><ol><li>Ein Maria-Datenbankmanagementsystem <ul><li>Das Datenbankmanagementsystem steuert den Multiuserzugriff auf die Datenbanken</li><li>Das Programm wird im Ordner <code>C:\\Programme\\SVWS-Server\\db</code> gespeichert</li><li>Die Datenbankdateien werden im Verzeichnis <code>C:\\ProgramData\\SVWS-Server\\data</code> gespeichert</li><li>Die Kennwörter für den Zugriff auf die Datenbanken werden in der Datei <code>C:\\ProgramData\\SVWS-Server\\res\\svwsconfig.json</code> gespeichert</li></ul></li><li>Eine Java-Laufzeitumgebung <ul><li>Dieses Programm ist notwendig, um den SVWS-Server auszuführen.</li><li>Die Laufzeitumgebung wird im Ordner <code>C:\\Programme\\SVWS-Server\\java</code> gespeichert</li></ul></li><li>Der SVWS-Server <ul><li>Der SVWS-Server fungiert als Dienstprogramm, welches logische Aufgaben übernimmt und den Zugriff auf die MariaDB-Datenbank regelt.</li><li>Das Programm wird im Ordner <code>C:\\Programme\\SVWS-Server\\svws-server</code> gespeichert.</li><li>Log-Dateien werden im Ordner <code>C:\\ProgramData\\SVWS-Server\\logs</code> gespeichert. Die Log-Dateien enthalten Informationen zu Fehlern bei der Ein- und Ausgabe des SVWS-Servers.</li></ul></li><li>Der SVWS-Client <ul><li>Der SVWS-Cient ermöglicht den browserbasierten Zugriff auf die Datenbanken und greift auf logische Aufgaben des SVWS-Servers zurück. Der SVWS-Client übernimmt die Aufgaben der Programme LuPO und Kurs42.</li><li>Der Client wird im Ordner <code>C:\\ProgramData\\SVWS-Server\\client</code> installiert.</li></ul></li><li>Eine SSL-Zertifikatsdatei <ul><li>Das Zertifikat muss später im System angemeldet werden, damit der SVWS-Client im Browser ohne Sicherheitswarnung gestartet werden kann.</li><li>Die SSL-Zertifikatsdatei wird im Ordner <code>C:\\Users\\&lt;benutzername&gt;\\Dokumente\\SVWS.cer</code> gespeichert.</li></ul></li></ol><h3 id="installation-des-svws-servers-auf-dem-windows-server" tabindex="-1">Installation des SVWS-Servers auf dem Windows-Server <a class="header-anchor" href="#installation-des-svws-servers-auf-dem-windows-server" aria-label="Permalink to &quot;Installation des SVWS-Servers auf dem Windows-Server&quot;">​</a></h3><p><img src="'+t+'" alt="Auswahl des Zielordners" loading="lazy"></p><p><em>Auswahl des Zielordners</em></p><p>Die neuste Version des SVWS-Servers kann hier heruntergeladen werden: <a href="https://github.com/SVWS-NRW/SVWS-Server/releases" target="_blank" rel="noreferrer">https://github.com/SVWS-NRW/SVWS-Server/releases</a></p><p>Führen Sie die Datei win64-installer-version.exe aus.</p><p>Es folgt ein Hinweisfenster der Benutzerkontensteuerung, dass durch die Installation Änderungen am Gerät vorgenommen werden. Klicken Sie hier auf die Schaltfläche <code>Weiter</code>.</p><p>Im folgenden Fenster akzeptieren Sie die Lizenzvereinbarung für die Installation des SVWS-Servers.</p><p>Anschließend können Sie die Installationspfade für das Datenbanksystem und das Programmverzeichnis auswählen. Für die Installation auf einem Server empfehlen wir, die vorgeschlagenen Pfade nicht zu ändern.</p><p><img src="'+a+'" alt="Konfigurieren der Installation" loading="lazy"></p><p><em>Konfigurieren der Installation</em></p><p>Es folgen die Konfigurationsangaben der SVWS-Server-Installation. Aktivieren Sie hier das Auswahlfeld zu &quot;Migriere aus einem Schild v2.x - Schema&quot;, damit während des Installationsprozesses die Daten einer SchILD-NRW 2 - Datenbank in die MariaDB migriert werden. Alle anderen Auswahlfelder sollten Sie so belassen.</p><p>Wenn die MariaDB installiert wird, wird automatisch ein Benutzer mit dem Namen &quot;root&quot; erzeugt. Dieser Benutzer hat als Super-Admin volle Zugriffsrechte auf alle Datenbanken, kann diese erzeugen und löschen. Legen Sie das root-Kennwort für diesen Benutzer fest und notieren Sie sich das Kennwort.</p><p>Der Installer schlägt Ihnen bereits ein sehr sicheres Kennwort vor, welches von einem Zufallsgenerator erzeugt wurde. Verwahren Sie dieses Kennwort an einem sichern Ort.</p>',28),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,[e("strong",null,"Bewahren Sie das root-Kennwort bei der zuständigen IT auf. Geht es verloren, muss diese den administrativen Zugang wiederherstellen; ein persönliches SchILD-Kennwort genügt dafür nicht.")]),e("p",null,"Jede Person mit Kenntnis des root-Kennworts kann sich als Super-Admin an allen Datenbanken anmelden.")],-1),i('<p>Sie können zudem den Port für den direkten Zugriff auf MariaDB eingeben. Geben Sie Datenbank-Host und Port in den dafür vorgesehenen Feldern an, beispielsweise Host <code>Servername</code> mit Port <code>3306</code>. Hier wird <strong>kein <code>https://</code></strong> vorangestellt. Die HTTPS-Adresse gehört zur getrennten Verbindung mit dem SVWS-Server.</p><p>Als Standard ist hier der Port 3306 eingetragen. Sie müssen die Portnummer nur dann ändern, wenn der Port 3306 bereits durch eine andere Anwendung belegt wird. Dies kann z.B. dann der Fall sein, wenn Sie ein anderes datenbankbasiertes Programm oder einen anderen datenbankbasierten Dienst installiert haben. Erhöhen Sie in einem solchen Fall die Portnummer z.B. auf 3307.</p><p>Vergeben Sie einen Namen für das Datenbank-Schema. Bei dem Datenbank-Schema handelt es sich um eine leere Datenbank, in der bereits alle Notwendigen Tabellen angelegt wurden. Im Gegensatz zu SchILD-NRW 2 gibt es keine Standarddatenbank. Jede Datenbank in SchILD-NRW 3 muss einen hier zu definierenden Namen erhalten.</p><p>Legen Sie einen <strong>Datenbank-Benutzer</strong> mit Kennwort an. Der Installer schlägt ein zufällig erzeugtes Kennwort vor. Dieser technische Zugang erhält Administrationsrechte auf die hier eingerichtete Schuldatenbank und wird von SchILD-NRW 3 für die Verbindung verwendet. Er gehört keiner bestimmten Person. Anders als der root-Zugang ist er im beschriebenen Aufbau auf diese eine Datenbank beschränkt.</p><p>Notieren Sie Benutzername und Kennwort für die Einrichtung der Verbindung und bewahren Sie die Angaben bei der zuständigen IT auf. Der root-Benutzer kann das Kennwort bei Bedarf zurücksetzen oder einen anderen Zugang für die Schuldatenbank einrichten.</p><p>Klicken Sie auf die Schaltfläche <code>Weiter</code>.</p><p><img src="'+s+'" alt="Angaben zum SSL-Zertifikat" loading="lazy"></p><p><em>Angaben zum SSL-Zertifikat</em></p><p>Im folgenden Fenster geben Sie den Zertifikatsnamen, den Schulnamen und den Schulort für die Zertifikatsdatei ein. Die Zertifikatsdatei wird während des Installationsprozesses erzeugt und muss in einem späteren Schritt im Betriebssystem installiert werden.</p><p><img src="'+d+'" alt="Zu migrierende Datenbank wählen" loading="lazy"></p><p><em>Zu migrierende Datenbank wählen</em></p><p>Wenn Sie das Auswahlfeld &quot;Migriere aus einem Schild v2.x - Schema&quot; aktiviert hatten, folgt nun ein Fenster, in welchem Sie Angaben zur Migration einer SchILD-NRW 2 - Datenbank vornehmen müssen. Wählen Sie hier das Datenbankformat der SchILD-NRW 2-Datenbank aus (Access MDB, MariaDB, MySQL, Microsoft SQL-Server).</p><p>Bei der Migration einer Access MDB müssen Sie den Dateipfad zur Access MDB angeben (z.B. schild200n.mdb). Bei der Migration einer MariaDB, MySQL- oder Microsoft SQL-Server-Datenbank müssen Sie einen Benutzernamen mit vollen Zugriffsrechten auf die Datenbank angeben. Zudem das zugehörige Passwort, den Ort der Datenbank (z.B. Servername oder Server-IP-Adresse 192.168.1.x) und den Namen des Schemas der Datenbank.</p><p><img src="'+l+'" alt="Info-Fenster während des Installationsprozesses" loading="lazy"></p><p><em>Info-Fenster während des Installationsprozesses</em></p><p>Im Anschluss können Sie die Installation starten. Während des Installationsprozesses wird die MariaDB installiert, der SVWS-Server installiert, die benötigte Java-Bibliothek installiert, die Konfigurationsdatei mit den Zugangsdaten auf die MariaDB gespeichert, die Zertifikatsdatei gespeichert und der SVWS-Server als Dienst gestartet. Im Anschluss wird noch die SchILD-NRW 2-Datenbank in das SchILD-NRW 3-Schema migriert.</p><p>Ein Anzeigefenster informiert Sie über den Fortschritt der Installation. Insbesondere die Migration der Datenbank kann einige Zeit in Anspruch nehmen.</p><h3 id="einrichten-einer-datenpartition-mit-ordnerstruktur" tabindex="-1">Einrichten einer Datenpartition mit Ordnerstruktur <a class="header-anchor" href="#einrichten-einer-datenpartition-mit-ordnerstruktur" aria-label="Permalink to &quot;Einrichten einer Datenpartition mit Ordnerstruktur&quot;">​</a></h3><p>Es empfiehlt sich, eine Datenpartition einzurichten. Erzeugen Sie in dieser Partition die Ordner <code>Programme</code>, <code>Users</code> und <code>Gruppen</code>. Vergeben Sie für den Ordner Programme lesende Rechte. Vergeben Sie für den Ordner Users individuelle Benutzerrechte. Vergeben Sie für den Ordner Gruppen individuelle Gruppenrechte.</p><p>Richten Sie einen Netzlaufwerkspfad für den Ordner Programme ein (z.B. P:). Richten Sie ebenfalls einen Netzlaufwerkspfad für den Ordner Gruppen ein (z.B. G:)</p><h3 id="installation-von-schild-nrw-3-1" tabindex="-1">Installation von SchILD-NRW 3 <a class="header-anchor" href="#installation-von-schild-nrw-3-1" aria-label="Permalink to &quot;Installation von SchILD-NRW 3&quot;">​</a></h3><p><img src="'+f+'" alt="Auswahl des Zielordners" loading="lazy"></p><p><em>Auswahl des Zielordners</em></p><p>Laden Sie das Installationspaket für den vorgesehenen Programmstand aus den <a href="https://github.com/SVWS-NRW/Schild-NRW-3/releases" target="_blank" rel="noreferrer">offiziellen SchILD-NRW-3-Releases</a> herunter. Achten Sie auf die dort genannte passende SVWS-Server-Version.</p><p>Installiert werden</p><ol><li>SchILD-NRW 3 im Ordner <code>P:\\SchILD-NRW3</code>, auf das nur lesende Rechte notwendig sind</li><li>ein Arbeitsverzeichnis im Ordner <code>G:\\SVWS-Arbeitsverzeichnis</code>, auf welches lesende und schreibende Rechte notwendig sind. Dieser Ordner wird z.B. die Connection-Dateien zur MariaDB und die Reports aufnehmen.</li><li>eine Connection-Datei schemaname.con im Ordner <code>G:\\SVWS-Arbeitsverzeichnis\\Connection-Files</code>. Die Connection-Datei (früher udl-Datei) ist eine Textdatei, welche Verbindungsdaten zur MariaDB enthält und in einem Texteditor geöffnet werden kann.</li></ol><p>Führen Sie die Datei Setup_SchILD3_vXYZ.exe aus. Es folgt ein Hinweisfenster der Benutzerkontensteuerung, dass durch die Installation Änderungen am Gerät vorgenommen werden. Klicken Sie hier auf die Schaltfläche <code>Weiter</code>.</p><p>Wählen Sie im folgenden Fenster den Installationsordner des Programms. Wir empfehlen, für die Server-Client-Installation den Ordner <code>P:\\SchILD-NRW3</code>. Klicken Sie hier auf die Schaltfläche <code>Weiter</code>.</p><p><img src="'+b+'" alt="Auswahl des Zielordners" loading="lazy"></p><p><em>Auswahl des Zielordners</em></p><p>Wählen Sie nun, wo das SVWS-Arbeitsverzeichnis erstellt werden soll. Für die Server-Client-Installation empfehlen wir den Ordner <code>G:\\SVWS-Arbeitsverzeichnis</code>. Klicken Sie hier auf die Schaltfläche <code>Weiter</code>.</p><p>Sie können nun angeben, unter welchem Programmnamen SchILD-NRW 3 im Startmenü und auf dem Desktop angezeigt werden soll. Wir empfehlen dringend, den vorgegebenen Namen nicht zu ändern. Klicken Sie hier auf die Schaltfläche <code>Weiter</code>.</p><p>SchILD-NRW 3 wird nun installiert. Ein Hinweisfenster informiert Sie über die erfolgreiche Installation und den Aufruf eines externen Programms zur Einrichtung der Konfigurationsdatei.</p><h4 id="die-verbindung-mit-schild-dbconfig-exe-konfigurieren-1" tabindex="-1">Die Verbindung mit SchILD_DBConfig.exe konfigurieren <a class="header-anchor" href="#die-verbindung-mit-schild-dbconfig-exe-konfigurieren-1" aria-label="Permalink to &quot;Die Verbindung mit SchILD_DBConfig.exe konfigurieren&quot;">​</a></h4><p><img src="'+k+'" alt="Konfiguration der Connection-Datei" loading="lazy"></p><p><em>Konfiguration der Connection-Datei</em></p><p>Direkt nach der Installation öffnet sich das Konfigurationstool, mittels dem die Datei erstellt wird, die notwendig ist, damit SchILD3 auf das Datenbankschema zugreifen kann.</p>',37),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Das Konfigurationstool kann bei Bedarf auch nachträglich aufgerufen werden, hierzu einfach die "),e("em",null,"SchILD_DBConfig.exe"),n(" im Installationsverzeichnis von SchILD3 als Windows-Administrator ausführen.")])],-1),i('<p>Im folgenden Fenster können Sie nun alle voreingetragenen Angaben prüfen, welche zur Erstellung einer Konfigurationsdatei notwendig sind.</p><ul><li>Als <strong>Server</strong> einer Server-Client-Installation ist entweder <code>Servername</code> oder die <code>IP-Adresse</code> einzutragen. Wir empfehlen die Eintragung des Servernamens.</li><li>Als <strong>Port</strong> ist der während der Installation des SVWS-Servers angegebene Port zur Datenbank eingetragen. Der Standard ist <code>3306</code>.</li><li>Als <strong>Datenbankschema</strong> ist der während der Installation des SVWS-Servers angegebene Name des Datenbankschemas eingetragen. Der Standardname lautet <code>svwsdb</code>.</li><li>Als <strong>Benutzername</strong> ist der während der Installation des SVWS-Servers angegebene Benutzername eingetragen. Der Standardbenutzer ist <code>svwsadmin</code>.</li><li>Als <strong>Benutzerpasswort</strong> ist das während der Installation des SVWS-Servers angegebene Benutzerpasswort für den Zugriff auf die Datenbank eingetragen.</li><li>Als <strong>URL für SVWS-Server</strong> ist die URL eingetragen, die im Browser zum Start des SVWS-Client eingetragen werden muss. Der Standard ist <code>https://Servername</code> oder <code>https://IP-Adresse</code>. Wir empfehlen den Servernamen.</li><li>Als <strong>Port</strong> für den Zugriff des SVWS-Clients auf die Datenbank ist der Port <code>443</code> eingetragen. Dies ist der Standard-Port für den verschlüsselten Zugriff des SVWS-Clients auf die Datenbank.</li><li>Durch das Auswahlfeld <code>Beim Verbindungstest berücksichtigen</code> kann dieser verschlüsselte SSL-Zugriff ebenfalls getestet werden, bevor die Konfigurationsdatei erzeugt wird. Die Aktivierung des Häkchens wird empfohlen.</li><li>Optional: Angaben zum Proxy-Server</li><li>Als <strong>Verzeichnis für die Konfigurationsdatei</strong> (Connection-File) wird standardmäßig ein Unterverzeichnis im SVWS-Arbeitsverzeichnis angeboten. Wir empfehlen die Einstellung unverändert zu übernehmen. Der Standardpfad lautet <code>C:\\SVWS-Arbeitsverzeichnis\\Connection-Files</code></li><li>Im letzten Feld können Sie einen <strong>Namen für die Konfigurationsdatei</strong> vergeben. Wir empfehlen hier den gleichen Namen zu verwenden, den auch das Schema trägt. So fällt eine Zuordnung der Konfigurationsdatei zum Schema leichter. Der Standardname ist <code>svwsdb</code></li></ul><p>Führen Sie die Verbindungstests für MariaDB und SVWS aus. Beide Tests müssen mit den eingetragenen Ports erfolgreich sein. Klicken Sie anschließend auf <strong>Datei speichern</strong>. Bestätigen Sie die Meldung über die gespeicherte Konfigurationsdatei und schließen Sie das Fenster mit <strong>Schließen</strong>.</p><h3 id="installation-des-ssl-zertifikats-1" tabindex="-1">Installation des SSL-Zertifikats <a class="header-anchor" href="#installation-des-ssl-zertifikats-1" aria-label="Permalink to &quot;Installation des SSL-Zertifikats&quot;">​</a></h3><p><img src="'+D+'" alt="Zertifikat installieren" loading="lazy"></p><p><em>Zertifikat installieren</em></p><p>Damit der SVWS-Client auf den Windows-Clients ohne störenden Sicherheitshinweis im Browser gestartet werden können, muss das SSL-Zertifikat, welches während des Installationsprozesses des SVWS-Servers erzeugt und gespeichert wurde, im Zertifikatsspeicher des jeweiligen Betriebssystems abgespeichert werden.</p><p>Windows übernimmt das Zertifikat mit dem Zertifikatimport-Assistenten in seinen Zertifikatsspeicher. Führen Sie diesen Schritt auf jedem Windows-Rechner aus, der als Client verwendet wird.</p><p>Navigieren Sie zum Windows-Systemordner &quot;Dokumente&quot;. Dort finden Sie eine Zertifikatsdatei mit dem Namen SVWS.cer. Führen Sie mit Hilfe eines Doppelklicks den Zertifikatimport-Assistenten aus.</p><p>Alternativ können Sie mit einem Rechtsklick den Kontextmenüeintrag &quot;Zertifikat installieren&quot; wählen. Es öffnet sich ein Informationsfenster mit Hinweisen zum Zertifikat. Klicken Sie auf die Schaltfläche <code>Zertifikat installieren</code>.</p><ol><li>Wählen Sie als Speicherort <strong>Lokaler Computer</strong>. Dafür benötigen Sie Windows-Administrationsrechte.</li><li>Klicken Sie auf <strong>Weiter</strong> und wählen Sie <strong>Alle Zertifikate in folgendem Speicher speichern</strong>.</li><li>Klicken Sie auf <strong>Durchsuchen…</strong> und wählen Sie <strong>Vertrauenswürdige Stammzertifizierungsstellen</strong>.</li><li>Bestätigen Sie mit <strong>OK</strong> und anschließend mit <strong>Weiter</strong>.</li></ol><p>Schließen Sie den Prozess mit Klick auf die Schaltfläche <code>Fertig stellen</code> ab. Ein Hinweisfenster informiert Sie über den erfolgreichen Import des Zertifikats.</p><h3 id="start-der-programme-1" tabindex="-1">Start der Programme <a class="header-anchor" href="#start-der-programme-1" aria-label="Permalink to &quot;Start der Programme&quot;">​</a></h3><p>Wir empfehlen, auf jedem Client eine Desktop-Verknüpfung auf <code>P:\\SchILD-NRW3\\SchILD30.exe</code> anzulegen.</p><p>SchILD-NRW 3 kann wie gewohnt über einen Doppelklick auf das Desktopsymbol oder über einen Einfachklick auf das Symbol im Startmenü gestartet werden.</p><p>Zum Start des SVWS-Clients öffnen Sie einen Browser. Tippen Sie dann in die Adresszeile die URL zum SVWS-Client ein (<code>https://Servername</code> oder <code>https://Server-IP-Adresse</code>) Es empfiehlt sich, einen Favoriten für diesen Link anzulegen. Sie können alternativ einen Browserlink zu dieser Adresse auf dem Desktop des PCs ablegen.</p><p>Für den Zugriff auf beide Programme müssen Sie sich als SchILD-Benutzer anmelden. Verwenden Sie hier die gleichen Zugangsdaten, die sie auch in SchILD-NRW 2 verwendet haben.</p><p>SchILD-NRW 3 und der SVWS-Client greifen gleichermaßen auf die MariaDB zu. Beide Programme verfügen über ebenbürtige Eintragungsmöglichkeiten, aber auch über unterschiedliche. So enthält der SVWS-Client die Funktionen von LuPO und Kurs42, während SchILD-NRW 3 Abiturberechnungen enthält.</p><p>In den kommenden Monaten werden die Fähigkeiten des SVWS-Clients stetig ausgebaut, so dass dieser später die gleichen Funktionalitäten enthalten wird, wie SchILD-NRW 3.</p><h2 id="update-der-programme" tabindex="-1">Update der Programme <a class="header-anchor" href="#update-der-programme" aria-label="Permalink to &quot;Update der Programme&quot;">​</a></h2><p><img src="'+w+`" alt="Update ausgewählter Komponenten" loading="lazy"></p><p><em>Update ausgewählter Komponenten</em></p><p>Für ein Update mit dem ZIP-Paket entpacken Sie dessen Inhalt in das bestehende Installationsverzeichnis von SchILD-NRW 3. Dabei werden die vorhandenen Programmdateien überschrieben.</p><p>Starten Sie für ein Update des SVWS-Servers den Installer. Wählen Sie im Konfigurationsfenster nur die zu aktualisierenden Komponenten aus. Lassen Sie <strong>Erstelle ein neues Schema</strong> und <strong>Migriere aus einem Schild v2.x - Schema</strong> ausgeschaltet. So aktualisieren Sie die Programmdateien, ohne eine neue Schuldatenbank anzulegen oder eine Migration zu starten.</p><h2 id="admin-ini" tabindex="-1">Admin.ini <a class="header-anchor" href="#admin-ini" aria-label="Permalink to &quot;Admin.ini&quot;">​</a></h2><p>In der Datei <code>Admin.ini</code> im Installationsverzeichnis von SchILD-NRW 3 können Administratorinnen und Administratoren Voreinstellungen festlegen. Öffnen und bearbeiten Sie die Datei mit einem Texteditor.</p><h3 id="parameter" tabindex="-1">Parameter <a class="header-anchor" href="#parameter" aria-label="Permalink to &quot;Parameter&quot;">​</a></h3><p>Folgende Parameter können hinterlegt werden:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Administration]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GroupDir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">={Pfad zum SVWS-Arbeitsverzeichnis}</span></span></code></pre></div><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Email]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MaxEmails</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">={max. Anzahl Empfänger}</span></span></code></pre></div><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Email]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SMTPServer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SMTPPort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SMTPLogin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">={0 oder 1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">; bei 1 wird ein explizites Login verwendet. Die Benutzer müssen dann ihre Zugangsdaten in SchILD-NRW 3 hinterlegen.}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SMTPSSL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">={0 oder 1}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SMTPStartTLS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">={0 oder 1}</span></span></code></pre></div><h3 id="erlauterung" tabindex="-1">Erläuterung <a class="header-anchor" href="#erlauterung" aria-label="Permalink to &quot;Erläuterung&quot;">​</a></h3><h4 id="groupdir" tabindex="-1">GroupDir <a class="header-anchor" href="#groupdir" aria-label="Permalink to &quot;GroupDir&quot;">​</a></h4><p>Die Pfadangabe zum SVWS-Arbeitsverzeichnis muss für den Zugriff auf Verbindungsdateien (Connections) und Reports zwingend angegeben werden. Der Eintrag wird während des Installationsprozesses von SchILD-NRW 3 automatisch vorgenommen.</p><p>Es können alle von Windows unterstützten Pfadangaben verwendet werden. Hierzu gehören auch UNC-Pfade.</p><h4 id="keepconnectionalive" tabindex="-1">KeepConnectionAlive <a class="header-anchor" href="#keepconnectionalive" aria-label="Permalink to &quot;KeepConnectionAlive&quot;">​</a></h4><p>Energiesparmodi können die Verbindung zwischen dem Arbeitsplatzrechner und dem Server unterbrechen. Mit diesem Parameter kann SchILD-NRW 3 regelmäßig ein Verbindungssignal (Ping) an den Server senden, um die Verbindung aufrechtzuerhalten.</p><h4 id="maxe-mails" tabindex="-1">MaxE-Mails <a class="header-anchor" href="#maxe-mails" aria-label="Permalink to &quot;MaxE-Mails&quot;">​</a></h4><p>Die meisten E-Mail-Provider beschränken die Anzahl der Empfänger pro E-Mail in den Feldern <code>An</code>, <code>Cc</code> und <code>Bcc</code>.</p><p>Hier können Sie die maximale Anzahl von Empfängern pro E-Mail hinterlegen. Überschreitet die Anzahl der Empfänger einer SchILD-NRW 3-Massen-E-Mail diesen Wert, teilt SchILD-NRW 3 die Empfänger automatisch auf mehrere E-Mails auf.</p><h4 id="smtp-angaben" tabindex="-1">SMTP-Angaben <a class="header-anchor" href="#smtp-angaben" aria-label="Permalink to &quot;SMTP-Angaben&quot;">​</a></h4><p>SMTPServer, SMTPPort, SMTPLogin, SMTPSSL, SMTPStartTLS</p><p>Anstatt die SMTP-Einstellungen in den globalen Einstellungen von SchILD-NRW 3 vorzunehmen, können diese Angaben zentral über die Datei <em>Admin.ini</em> bereitgestellt werden.</p><p>Dies kann beispielsweise sinnvoll sein, wenn ein Schulträger oder kommunaler IT-Dienstleister einen gemeinsamen E-Mail-Provider für mehrere Schulen zur Verfügung stellt.</p><h2 id="deinstallieren-der-programme" tabindex="-1">Deinstallieren der Programme <a class="header-anchor" href="#deinstallieren-der-programme" aria-label="Permalink to &quot;Deinstallieren der Programme&quot;">​</a></h2><h3 id="deinstallation-uber-die-einstellungen-von-windows" tabindex="-1">Deinstallation über die Einstellungen von Windows <a class="header-anchor" href="#deinstallation-uber-die-einstellungen-von-windows" aria-label="Permalink to &quot;Deinstallation über die Einstellungen von Windows&quot;">​</a></h3><p>Sie können den SVWS-Server und SchILD-NRW 3 auf einem PC mit Windows-Betriebssystem wie gewohnt unter <em>Einstellungen ➜ Apps ➜ Installierte Apps&#39;</em> deinstallieren. Sichern Sie vorab alle Datenbankdaten, welche Sie behalten möchten.</p><p>Nach der Deinstallation verbleiben einige Ordner auf dem System, die vor einer Neuinstallation manuell gelöscht werden sollten, da es andernfalls zu Problemen bei einer Neuinstallation kommen wird. Bedenken Sie jedoch, dass nach dem Löschen auch alle Datenbank-Daten im SVWS-Datenbank Ordner gelöscht werden:</p><ul><li>Der SchILD-NRW 3 Programmordner <code>C:\\Programme (x86)\\SchILD3.0</code> oder <code>C:\\Program Files (x86)\\SchILD3.0</code></li><li>Der SVWS-Server Ordner <code>C:\\Programme\\SVWS-Server</code> oder <code>C:\\Program Files\\SVWS-Server</code></li><li>Der SVWS-Datenbank Ordner <code>C:\\ProgramData\\SVWS-Server</code></li><li>Den Unterordner Connection-Files im SVWS-Arbeitsverzeichnis unter <code>C:\\SVWS-Arbeitsverzeichnis\\Connection-Files</code></li></ul><p>Der Ordner <code>ProgramData</code> ist als Systemordner standardmäßig unsichtbar. Sie können entweder den Pfad in die Adressleiste des Datei-Explorers eintippen, oder in der Ansicht des Datei-Explorers ausgeblendete Elemente anzeigen lassen. Um die Ordner im Verzeichnis <code>ProgramData</code> und <code>Programme</code> bzw. <code>Program Files</code> löschen zu können sind Admin-Rechte notwendig.</p><h3 id="batch-datei-als-alternative" tabindex="-1">Batch-Datei als Alternative <a class="header-anchor" href="#batch-datei-als-alternative" aria-label="Permalink to &quot;Batch-Datei als Alternative&quot;">​</a></h3><p>Sie können hier eine Batch-Datei als ZIP-Datei herunterladen, welche den gesamten Deinstallationsprozess übernimmt.</p><ul><li>Die Datei löscht auf Wunsch den Schild-Installationsordner und zugehörige Einträge in der Registry.</li><li>Die Datei stoppt und löscht auf Wunsch alle SVWS-Dienste, den SVWS-Installationsordner, den Maria-DB Installationsordner und zugehörige Einträge in der Registry.</li><li>Die Datei löscht auf Wunsch alle Connection-Dateien im SVWS-Arbeitsverzeichnis.</li></ul><p><strong>Bedienung</strong></p><ol><li>Laden Sie die ZIP-Datei herunter</li><li>Entpacken Sie die ZIP-Datei</li><li>Öffnen Sie die BAT-Datei in einem Editor</li><li>Passen Sie bei Bedarf die Pfade an und speichern Sie die Datei</li><li>Führen Sie die Datei über das Kontextmenü als Administrator aus</li></ol><p><strong>Die Batch-Datei wird sie durch den Deinstallations-Prozess führen.</strong></p>`,56),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis – ⬇️Download")]),e("p",null,[e("a",{href:"/dateien/installation/delete-svws-server-and-schild-nrw-3.zip"},"Delete SVWS-Server and SchILD-NRW 3.zip")])],-1),i('<p>Vertrauen Sie nur BAT-Dateien aus sicheren Quellen, da diese Schaden im System anrichten können</p><h2 id="testen-und-melden-von-fehlern-in-schild-nrw-3" tabindex="-1">Testen und melden von Fehlern in SchILD-NRW 3 <a class="header-anchor" href="#testen-und-melden-von-fehlern-in-schild-nrw-3" aria-label="Permalink to &quot;Testen und melden von Fehlern in SchILD-NRW 3&quot;">​</a></h2><p>Fehler können Sie im GitHub-Ticketsystem melden. Ein solcher Eintrag heißt dort <strong>Issue</strong>. Wenn Sie unsicher sind, ob ein Programmfehler oder eine Bedienungsfrage vorliegt, beschreiben Sie das Problem zunächst im <a href="https://schulverwaltungsinfos.nrw.de/svws/forum/index.php" target="_blank" rel="noreferrer">Anwenderforum</a>:</p><p><a href="https://github.com/SVWS-NRW/Schild-NRW-3/issues" target="_blank" rel="noreferrer">https://github.com/SVWS-NRW/Schild-NRW-3/issues</a></p><p>Um Fehlerbilder (Issues) zu melden oder zu kommentieren benötigen Sie einen kostenlosen GitHub-Account.</p><p>Bitte beachten Sie, dass Sie zunächst die bestehenden Issues sichten, bevor Issues doppelt angelegt werden. Benutzen Sie hierzu auch gerne die Suchfunktion.</p><p>Beschreiben Sie den Fehler bitte so genau, wie möglich. Präzise Angaben zur Versionsnummer des Programms, des Workflows und des Fehlerbildes helfen, die Ursache ausfindig zu machen.</p>',7),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Bitte schreiben Sie alle Fehlermeldungen in das Ticketsystem bei Github, es sei denn, es handelt sich um sensible sicherheitsrelevante oder datenschutz-technische Probleme. Melden Sie solche Probleme bitte unbedingt per E-Mail an die Support-Adresse.")],-1),i('<p><a href="/administration/">index.php?title=Kategorie:Installation</a> <a href="/schild3/">index.php?title=Kategorie:SchILD-NRW</a> <a href="/administration/">index.php?title=Kategorie:SVWS-Server</a> <a href="/administration/">index.php?title=Kategorie:Administration</a> <a href="/hilfe/">index.php?title=Kategorie:Video</a></p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Installation_SVWS-Server_und_SchILD-NRW_3" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7228.</p>',3)])])}const C=h(v,[["render",z]]);export{N as __pageData,C as default};
